import java.util.concurrent.atomic.AtomicInteger;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;

private final AtomicInteger refs = new AtomicInteger();

// VarHandle: atomics on an existing field, no wrapper object
private volatile int state;
private static final VarHandle STATE;
static {
    try { STATE = MethodHandles.lookup().findVarHandle(Account.class, "state", int.class); }
    catch (ReflectiveOperationException e) { throw new ExceptionInInitializerError(e); }
}

boolean tryAcquire() {
    return STATE.compareAndSet(this, 0, 1);      // acquire-release semantics
}
void publish(Node n) {
    STATE.setRelease(this, n);                    // release store: publishes prior writes
}
